import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Seguridad — Formado en el ataque, mentalizado en la defensa","description":"Kit de pentesting, investigación XSS, análisis estático — encontrar agujeros antes que los demás.","frontmatter":{"title":"Seguridad — Formado en el ataque, mentalizado en la defensa","description":"Kit de pentesting, investigación XSS, análisis estático — encontrar agujeros antes que los demás."},"headers":[],"relativePath":"es/skills/security/index.md","filePath":"es/skills/security/index.md"}`),a={name:`es/skills/security/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="seguridad-—-formado-en-el-ataque-mentalizado-en-la-defensa" tabindex="-1">Seguridad — Formado en el ataque, mentalizado en la defensa <a class="header-anchor" href="#seguridad-—-formado-en-el-ataque-mentalizado-en-la-defensa" aria-label="Permalink to “Seguridad — Formado en el ataque, mentalizado en la defensa”">​</a></h1><p>Aprendí seguridad desde el lado ofensivo — construyendo escáneres, estudiando XSS, auditando código en busca de patrones inseguros — porque no puedes defender un sistema que no puedes atacar. Esa lente ahora corre sobre todo lo que envío, especialmente el código escrito por agentes.</p><h2 id="el-arsenal" tabindex="-1">El arsenal <a class="header-anchor" href="#el-arsenal" aria-label="Permalink to “El arsenal”">​</a></h2><ul><li><strong>Análisis estático</strong> — mi proyecto <a href="https://github.com/Godde3s/explorer" target="_blank" rel="noreferrer">explorer</a> caza patrones vulnerables y rutas de código inseguras en árboles de fuente.</li><li><strong>Investigación de exploits web</strong> — flujos XSS, patrones de acceso inverso (<a href="https://github.com/Godde3s/access" target="_blank" rel="noreferrer">access</a>), utilidades de caza de bugs (<a href="https://github.com/Godde3s/thehunter" target="_blank" rel="noreferrer">thehunter</a>).</li><li><strong>Alfabetización de herramientas</strong> — la colección clásica (<a href="https://github.com/Godde3s/Collection-" target="_blank" rel="noreferrer">Collection-</a>) que todo practicante debería saber leer.</li><li><strong>Práctica de endurecimiento</strong> — paneles admin con token + 2FA, bóvedas de sesión cifradas, despliegues de superficie mínima.</li></ul><h2 id="seguridad-en-la-era-agentica" tabindex="-1">Seguridad en la era agéntica <a class="header-anchor" href="#seguridad-en-la-era-agentica" aria-label="Permalink to “Seguridad en la era agéntica”">​</a></h2><p>Los agentes escriben más código que nunca, y lo escriben <em>con confianza</em> — incluido el tipo inseguro. Mi checklist de revisión por eso trata cada diff generado como entrada no confiable: superficies de inyección, bypasses de autenticación, manejo de secretos, procedencia de dependencias. La <a href="/Usf/es/about/how-i-work/">página del método</a> llama a esto el paso de revisión humana; en términos de seguridad, es el único paso que importa.</p><div class="warning custom-block"><p class="custom-block-title">Cláusula ética</p><p>Mi trabajo ofensivo apunta a sistemas que poseo o estoy autorizado a probar. Cualquier otra cosa es un crimen, no una habilidad.</p></div>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};